        const auto velocityResult = scriptBuiltins.invoke(
            SvScriptBuiltinKind::Method, "getvelocity", playerObject);
        const auto onGroundResult = scriptBuiltins.invoke(
            SvScriptBuiltinKind::Method, "isonground", playerObject);
        const std::array<SvScriptValue, 1> sameTeamArguments{ playerObject };
        const auto sameTeamResult = scriptBuiltins.invoke(
            SvScriptBuiltinKind::Method,
            "issameteam",
            playerObject,
            sameTeamArguments);
        const std::array<SvScriptValue, 1> scoreArguments{ std::int64_t{ 100 } };
        const std::array<SvScriptValue, 1> xpArguments{ std::int64_t{ 50 } };
        const std::array<SvScriptValue, 1> teamScoreArguments{ std::int64_t{ 1 } };
        const std::array<SvScriptValue, 1> killArguments{ std::int64_t{ 1 } };
        const auto addScoreResult = scriptBuiltins.invoke(
            SvScriptBuiltinKind::Method, "addscore", playerObject, scoreArguments);
        const auto addXpResult = scriptBuiltins.invoke(
            SvScriptBuiltinKind::Method, "addxp", playerObject, xpArguments);
        const auto addTeamScoreResult = scriptBuiltins.invoke(
            SvScriptBuiltinKind::Method,
            "addteamscore",
            playerObject,
            teamScoreArguments);
        // addkill is free-for-all's counterpart to addteamscore: the counter the
        // score limit reads, in kills, kept apart from the 100-a-kill display
        // score. Without it the limit compared 30 against a points total and
