        const std::int32_t throwingTimer=7950;
        std::memcpy(throwingNative.bytes.data()+0x400,&throwingFlags,4);
        std::memcpy(throwingNative.bytes.data()+0x4C,&throwingEntity,4);
        std::memcpy(throwingNative.bytes.data()+0x48,&throwingTimer,4);
        auto throwingSource=nativeProjectionResult;
