        std::size_t clientEventsHandlerCalls{};
        bool clientEventsHandlerReceivedContext = true;
        std::vector<SvNativePredictableEvent> handledPredictableEvents;
        std::vector<std::uint32_t> weaponMovementCommandTimes;
