                require(w->beginFrame(50,ActiveClients) && w->clientThink(0,UserCmd{.commandTime=time}) &&
                    w->endFrame(ActiveClients) && w->runFrame(50,ActiveClients),"face lethal transition");
                const auto dead=w->entity({*actor,0});
                require(dead.has_value(),"face dying body retained");
                if(enabled)
                    require(std::ranges::any_of(dead->networkState.events,[](const auto &e){return e==SvEntityEvent{115,190|(255<<9)};}) &&
                        std::ranges::any_of(dead->networkState.events,[](const auto &e){return e==SvEntityEvent{115,248|(255<<9)};}),
                        "death stops both exact owned assets with bone wildcard");
                const auto seq=dead->networkState.actorField00B4;
                for(unsigned i=0;i<6;++i)require(w->runFrame(50,ActiveClients),"face corpse ticks");
                require(w->entity({*actor,0})->networkState.actorField00B4==seq,"no restart on dead body");
                require(w->freeEntity({*actor,0}),"free face owner");
                w->reset();w->setZmActorNamespaceEnabled(true);
                require(w->configureEntityPool(128) && w->configureSpawn({},{}),"reset face map");
                const auto fresh=w->spawnZombieActor({.origin={128,0,0}},287,307);
                require(fresh.has_value(),"new map actor");
