                outfit.leftArmOff=299;outfit.leftArmBone=27;outfit.shockBone=10;
                SvZmDeathFx fx{197,225};fx.bo1Derived=true;fx.refined=true;fx.shock=180;
                const std::array outfits{outfit};
                const std::array clips{SvZmDeathClip{647,4750,1,648,660,350,3250,true},SvZmDeathClip{517,2250,1}};
                w->setZmPresentation(outfits,clips,fx);require(w->runFrame(50,ActiveClients),"refined player");
                const auto actor=w->spawnZombieActor({.origin={128,0,0}},287,307);require(actor.has_value(),"refined actor");
                std::optional<SvEntityDamagePayload> pending;
