                for(const auto &p:FactoryPowerPieces) {
                    if(p.brush)brushes.push_back({.walkEntityNum=p.number,.origin=p.origin,
                        .collision={.clipHandle=static_cast<std::uint16_t>(p.brush),.bounds={{0,0,0},{8,8,8}},.contents=1}});
                    else models.push_back({.walkEntityNum=p.number,.origin=p.origin,.angles=p.raised,
                        .modelIndex=267,.modelName=p.number==343?"codo_asylum_electric_switch_off":"zombie_power_lever_handle_arm03_off"});
                }
                power->setZmBoardTrajectoryEvaluator([](const SvNativeTrajectory &t,int at,std::array<float,3>&out){
                    const float age=std::clamp(float(at-t.time)*0.001f,0.0f,float(t.duration)*0.001f);
                    const float duration=float(t.duration)*0.001f;
                    float dt=0;
                    if(t.type==3)dt=age;
                    else if(t.type==7 && duration>0)dt=0.5f*age*age/duration;
                    else if(t.type==8 && duration>0)dt=age-0.5f*age*age/duration;
                    else if(t.type!=0)return false;
                    for(unsigned k=0;k<3;++k)out[k]=t.base[k]+t.delta[k]*dt;return true;
                });
                require(power->configureSpawnAndBrushModelEntities({}, {},FirstDynamicServerEntityNum,brushes,models,{},"zm_factory_sh","zm"),"eight-piece Factory map fixture");
                require(power->runFrame(50,{}),"initial power frame");
                require(power->entity({473,0})->currentAngles[0]==-90 && power->entity({474,0})->currentAngles[0]==90,
                    "unpowered bridge geometry is raised");
                bool rejectNext=false, rejectAll=false;
                power->setNativeEntityMirrorSynchronizer([&](SvNativeEntityMirrorPhase,
                    std::span<const SvCollisionEntity>,
                    std::span<const SvNativeEntityStateSource>,std::uint32_t) {
                    return !rejectAll && !std::exchange(rejectNext,false);
                });
                const auto before=power->entity({344,0});
                const auto bodyBefore=power->entity({343,0});
