                auto invalidSteam=powerSnapshot;
                for(auto &e:invalidSteam.entities)if(e.eType==EntityTypeExploder)e.eventParm=256;
                require(!SV_ValidateSnapshotFrame(invalidSteam),"exploder admission retains the native eight-bit parameter bound");
